inline const GLX *GetGLX(const void *buf) {
  return ::flatbuffers::GetRoot<GLX>(buf);
}

inline const GLX *GetSizePrefixedGLX(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<GLX>(buf);
}

inline const char *GLXIdentifier() {
  return "$GLX";
}

inline bool GLXBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GLXIdentifier());
}

inline bool SizePrefixedGLXBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GLXIdentifier(), true);
}

template <bool B = false>
inline bool VerifyGLXBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<GLX>(GLXIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedGLXBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<GLX>(GLXIdentifier());
}

inline void FinishGLXBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GLX> root) {
  fbb.Finish(root, GLXIdentifier());
}

inline void FinishSizePrefixedGLXBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GLX> root) {
  fbb.FinishSizePrefixed(root, GLXIdentifier());
}

